  variant?: "primary" | "success" | "info" | "warning";
}

const SIZE_MAP = {
  sm: "h-1.5",
  md: "h-2.5",
  lg: "h-4",
};

const VARIANT_BAR = {
  primary: "bg-primary",
  success: "bg-emerald-500",
  info: "bg-sky-500",
  warning: "bg-amber-500",
};

export const Progress = React.forwardRef<HTMLDivElement, ProgressProps>(
