export function SplitPane({
  aside,
  stickyFirst = false,
  stickyAside,
  stackBreakpoint = "lg",
  ratio = "5/7",
  minAside = "320px",
  gap = "lg",
  className,
  children,
  ...props
}: SplitPaneProps) {
  const isSticky = stickyAside !== undefined ? stickyAside : stickyFirst;
  const minW = typeof minAside === "number" ? `${minAside}px` : minAside;

  const gridColsClass =
    ratio === "1/1"
      ? "lg:grid-cols-2"
      : ratio === "1/2"
      ? "lg:grid-cols-[1fr_2fr]"
      : ratio === "2/1"
      ? "lg:grid-cols-[2fr_1fr]"
      : ratio === "1/3"
      ? "lg:grid-cols-[1fr_3fr]"
      : ratio === "3/1"
      ? "lg:grid-cols-[3fr_1fr]"
      : `lg:grid-cols-[minmax(${minW},5fr)_minmax(0,7fr)]`;

  return (
    <div
      className={cn(
        "grid items-start w-full",
        gridColsClass,
        GAP_MAP[gap],
        className
      )}
      {...props}
    >
      {aside !== undefined ? (
        <>
          <SplitPaneAside sticky={isSticky}>{aside}</SplitPaneAside>
          <SplitPaneMain>{children}</SplitPaneMain>
        </>
      ) : (
        children
      )}
    </div>
  );
}

