import * as React from "react";
import { cn } from "@/lib/utils";

export type PackageManagerType = "pnpm" | "npm" | "bun" | "yarn";

export interface PackageManagerProps extends React.HTMLAttributes<HTMLDivElement> {
  pkg?: string;
  defaultManager?: PackageManagerType;
}

export function PackageManager({
  pkg = "array-ui",
  defaultManager = "pnpm",
  className,
  ...props
}: PackageManagerProps) {
  const [manager, setManager] = React.useState<PackageManagerType>(defaultManager);
  const [copied, setCopied] = React.useState(false);

  const getCommand = (pm: PackageManagerType) => {
    switch (pm) {
      case "pnpm":
        return `pnpm add ${pkg}`;
      case "bun":
        return `bun add ${pkg}`;
      case "yarn":
        return `yarn add ${pkg}`;
      case "npm":
      default:
        return `npm install ${pkg}`;
    }
  };

  const command = getCommand(manager);

  const handleCopy = () => {
    navigator.clipboard.writeText(command);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div
      className={cn(
        "rounded-lg border border-border bg-card text-card-foreground overflow-hidden shadow-xs my-4",
        className
      )}
      {...props}
    >
      <div className="flex items-center justify-between border-b border-border bg-muted/30 px-3 py-1.5">
        <div className="flex items-center gap-1">
          {(["pnpm", "npm", "bun", "yarn"] as PackageManagerType[]).map((pm) => (
            <button
              key={pm}
              type="button"
              className={cn(
                "px-2.5 py-1 text-xs font-mono font-medium rounded-md transition-colors cursor-pointer",
                manager === pm
                  ? "bg-background text-foreground shadow-2xs border border-border"
                  : "text-muted-foreground hover:text-foreground"
              )}
              onClick={() => setManager(pm)}
            >
              {pm}
            </button>
          ))}
        </div>
      </div>
      <div className="flex items-center justify-between px-4 py-3 bg-[#09090b] text-[#ececf1]">
        <code className="font-mono text-sm">{command}</code>
        <button
          type="button"
          className="text-xs px-2.5 py-1 rounded bg-zinc-800 hover:bg-zinc-700 text-zinc-200 transition-colors cursor-pointer"
          onClick={handleCopy}
        >
          {copied ? "Copied!" : "Copy"}
        </button>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export interface FileTreeNode {
  name: string;
  type?: "file" | "folder";
  children?: FileTreeNode[];
  badge?: string;
  defaultOpen?: boolean;
}

export interface FileTreeProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  data: FileTreeNode[];
  onSelect?: (item: FileTreeNode) => void;
  selected?: string;
}

function FileTreeNodeItem({
  node,
  onSelect,
  selected,
}: {
  node: FileTreeNode;
  onSelect?: (item: FileTreeNode) => void;
  selected?: string;
}) {
  const isFolder = node.type === "folder" || Boolean(node.children && node.children.length > 0);
  const [isOpen, setIsOpen] = React.useState(node.defaultOpen ?? true);
  const isSelected = selected === node.name;

  return (
    <div className="text-xs font-mono select-none">
      <div
        className={cn(
          "flex items-center gap-1.5 px-2 py-1 rounded cursor-pointer transition-colors",
          isSelected ? "bg-muted font-semibold text-foreground" : "text-muted-foreground hover:text-foreground hover:bg-muted/50"
        )}
        onClick={(e) => {
          e.stopPropagation();
          if (isFolder) setIsOpen(!isOpen);
          onSelect?.(node);
        }}
      >
        <span className="w-3 text-center text-[10px] text-muted-foreground">
          {isFolder ? (isOpen ? "▾" : "▸") : "•"}
        </span>
        <span className="flex-1">{node.name}</span>
        {node.badge && (
          <span className="text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground">
            {node.badge}
          </span>
        )}
      </div>
      {isFolder && isOpen && node.children && (
